import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    # Validate input parameters
    if interval <= 0 or duration <= 0:
        raise ValueError("Both 'interval' and 'duration' must be greater than zero.")

    # Determine the appropriate command based on the operating system
    system = platform.system().lower()
    if system == "windows":
        # Windows: Use typeperf to get CPU usage
        command = ["typeperf", "\\Processor(_Total)\\% Processor Time", "-sc", "1"]
    else:
        # Unix/Linux: Use top in batch mode to get CPU usage
        command = ["top", "-bn1", "|", "grep", "%Cpu(s)"]

    data = []
    start_time = time.time()
    end_time = start_time + duration

    try:
        while time.time() < end_time:
            # Record the current timestamp
            timestamp = time.time()

            # Execute the command to get CPU usage
            if system == "windows":
                result = subprocess.run(command, capture_output=True, text=True, shell=True)
                output = result.stdout.strip()
                # Parse the output from typeperf
                # Example output: "(PDH-CSV 4.0) (Local Computer Time)", "\\Processor(_Total)\\% Processor Time", "5.123456"
                try:
                    lines = output.split('\n')
                    if len(lines) >= 2:
                        # The second line contains the data
                        parts = lines[1].split(',')
                        if len(parts) >= 3:
                            cpu_usage = float(parts[2].strip('"'))
                        else:
                            cpu_usage = 0.0
                    else:
                        cpu_usage = 0.0
                except (ValueError, IndexError):
                    cpu_usage = 0.0
            else:
                # Unix/Linux: Use ps command to get CPU usage
                result = subprocess.run(["ps", "-eo", "%cpu", "--sort=-%cpu", "|", "head", "-2"], 
                                      capture_output=True, text=True, shell=True)
                output = result.stdout.strip()
                try:
                    lines = output.split('\n')
                    if len(lines) >= 2:
                        # The second line contains the highest CPU usage
                        cpu_usage = float(lines[1].strip())
                    else:
                        cpu_usage = 0.0
                except (ValueError, IndexError):
                    cpu_usage = 0.0

            # Append the record
            data.append({
                "timestamp": timestamp,
                "cpu_usage_percent": cpu_usage
            })

            # Wait for the specified interval
            time.sleep(interval)

    except IOError:
        return None

    # Write data to log file
    try:
        with open(LOGFILE_PATH, 'w') as f:
            json.dump(data, f, indent=2)
    except IOError:
        return None

    return LOGFILE_PATH

