import subprocess
import os
import time
import glob
def task_func(r_script_path: str, output_path: str, duration: int) -> (bool, str):
    """
    Executes an R script and verifies if the output file is generated within a given duration.

    Args:
        r_script_path: Path to the R script to execute.
        output_path: Path pattern or exact path of the expected output file(s).
        duration: Maximum time in seconds to wait for the output file.

    Returns:
        tuple: (bool, str) where bool is True if file generated within duration, False otherwise.
    """
    # Record start time
    start_time = time.time()

    # Start the R script execution
    try:
        process = subprocess.Popen(
            ['Rscript', r_script_path],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE
        )
    except FileNotFoundError:
        return (False, "Rscript not found. Please ensure R is installed and in PATH.")
    except Exception as e:
        return (False, f"Failed to start R script: {str(e)}")

    # Poll for file existence within the specified duration
    while time.time() - start_time < duration:
        # Check if process has finished
        if process.poll() is not None:
            # Process finished, check for output file
            matching_files = glob.glob(output_path)
            if matching_files:
                return (True, 'File generated successfully within the specified duration.')
            else:
                # Get any error output from the process
                _, stderr = process.communicate()
                if stderr:
                    return (False, f"File not generated. R script error: {stderr.decode('utf-8', errors='ignore')}")
                return (False, 'File not generated within the specified duration.')

        # Check if output file exists yet
        matching_files = glob.glob(output_path)
        if matching_files:
            # File found before duration expired
            # Wait a tiny bit to ensure process might finish cleanly
            time.sleep(0.1)
            return (True, 'File generated successfully within the specified duration.')

        # Small sleep to prevent CPU spinning
        time.sleep(0.1)

    # Duration expired - terminate the process if still running
    if process.poll() is None:
        process.terminate()
        try:
            process.wait(timeout=5)
        except subprocess.TimeoutExpired:
            process.kill()
            process.wait()

    # Final check for output file
    matching_files = glob.glob(output_path)
    if matching_files:
        return (True, 'File generated successfully within the specified duration.')

    return (False, 'File not generated within the specified duration.')

