    Args:
        r_script_path (str): Path to the R script to execute.
        output_path (str): Path to the expected output file (can include wildcards).
        duration (int): Maximum time in seconds to wait for the file to be generated.

    Returns:
        tuple: (bool, str) - Success status and message.
    """
    # Remove any existing matching files before running the script
    existing_files = glob.glob(output_path)
    for f in existing_files:
        try:
            os.remove(f)
        except OSError:
            pass

    # Start the R script execution
    start_time = time.time()
    try:
        process = subprocess.Popen(
            ["Rscript", r_script_path],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE
        )
    except FileNotFoundError:
        return (False, "Rscript not found. Please ensure R is installed and in PATH.")
    except Exception as e:
        return (False, f"Failed to start R script: {str(e)}")

    # Wait for the file to be generated within the specified duration
    file_found = False
    while time.time() - start_time < duration:
        # Check if process has finished
        if process.poll() is not None:
            # Process finished, check if file exists now
            matching_files = glob.glob(output_path)
            if matching_files:
                file_found = True
                break
            else:
                # Process finished but no file found
                _, stderr = process.communicate()
                error_msg = stderr.decode('utf-8', errors='replace').strip()
                if error_msg:
                    return (False, f"R script finished with error: {error_msg}")
                else:
                    return (False, "R script finished but output file was not generated.")

        # Check if file exists while process is still running
        matching_files = glob.glob(output_path)
        if matching_files:
            file_found = True
            break

        # Sleep briefly to avoid busy waiting
        time.sleep(0.1)

    # If time expired and no file found
    if not file_found:
        # Terminate the process if still running
        if process.poll() is None:
            process.terminate()
            try:
                process.wait(timeout=5)
            except subprocess.TimeoutExpired:
                process.kill()
        return (False, "File not generated within the specified duration.")

    # File was generated successfully
    return (True, "File generated successfully within the specified duration.")

