import subprocess
import os
import threading
def task_func(script_path: str, timeout: int = 60) -> str:
    # Check if file exists
    if not os.path.isfile(script_path):
        raise FileNotFoundError(f"Script file not found: {script_path}")

    result = {"message": None}

    def run_script():
        try:
            process = subprocess.run(
                ["python", script_path],
                capture_output=True,
                text=True,
                timeout=timeout
            )
            result["message"] = "Script executed successfully."
        except subprocess.TimeoutExpired:
            result["message"] = "Terminating process due to timeout."
        except Exception as e:
            result["message"] = f"Script execution failed: {str(e)}"

    thread = threading.Thread(target=run_script)
    thread.daemon = True
    thread.start()
    thread.join(timeout=timeout + 5)  # Give a small buffer

    # If thread is still alive after timeout, it means the script is still running
    if thread.is_alive():
        result["message"] = "Terminating process due to timeout."

    return result["message"]

